import{c as t,Q as o,j as n,m as a}from"./chunks/framework.BqPkuuVc.js";const r="/assets/station-memory.DQ7Qmfgv.png",m=JSON.parse('{"title":"Station memory","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/station-memory.md","filePath":"user/running-the-event/station-memory.md"}'),s={name:"user/running-the-event/station-memory.md"};function i(d,e,h,c,l,g){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="station-memory" tabindex="-1">Station memory <a class="header-anchor" href="#station-memory" aria-label="Permalink to &quot;Station memory&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators reading a SportIdent unit&#39;s memory: to account for everyone, recover punches the radio missed, or check a unit&#39;s clock.</p><p>Every SportIdent control unit keeps a backup of every card that punched it. Reading that memory into Manager tells you, for certain, who punched the start, the check or the finish, even when the radio didn&#39;t hear them.</p><h2 id="when-to-read-a-station" tabindex="-1">When to read a station <a class="header-anchor" href="#when-to-read-a-station" aria-label="Permalink to &quot;When to read a station&quot;">​</a></h2><ul><li><strong>At the end of the day, to account for everyone.</strong> Read the <strong>finish</strong> unit: anyone in it came back. That&#39;s the strongest way to clear the <strong>On course</strong> list. See <a href="./safety-check#reading-sportident-stations">Safety check</a>.</li><li><strong>After the start, to find the non-starters.</strong> Read the <strong>check</strong> or <strong>start</strong> unit: anyone entered who isn&#39;t in it, and nothing else has seen, didn&#39;t start.</li><li><strong>When a radio control or radio finish missed people</strong>, or you suspect a unit misbehaved.</li><li><strong>Before the event, to check a unit&#39;s clock</strong> against the computer&#39;s.</li></ul><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A SportIdent USB station (a BSM7 or BSM8) plugged into the computer you&#39;re using, and connected in the browser. Manager calls it the <strong>direct station</strong>; it&#39;s the same reader card download uses.</li><li>The <strong>coupling rod</strong>, to connect it to the unit you&#39;re reading, which Manager calls the <strong>remote station</strong>.</li><li>A browser with Web Serial: Chrome, Edge, or Firefox 151 or later. On a computer other than the server, use the secure link (see <a href="./../reference/https-and-certificates">HTTPS and certificates</a>). On a Mac you also need the CP210x driver (see <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>).</li></ul><p><strong>One reader serves the whole of Manager.</strong> Connect the station here, on the dashboard&#39;s <strong>Download card</strong> tile, on the <strong>Card downloads</strong> page or on <strong>Station configuration</strong>, and it&#39;s the same reader everywhere, with card download still working. Card downloads pause while a memory is read, cleared or a clock set, and carry on afterwards. A card presented during one of those isn&#39;t downloaded and has to be presented again, and a memory read is refused while a card is being downloaded. Disconnecting here disconnects card download too.</p><h2 id="reading-a-station" tabindex="-1">Reading a station <a class="header-anchor" href="#reading-a-station" aria-label="Permalink to &quot;Reading a station&quot;">​</a></h2><p>Open the event and choose <strong>SportIdent station</strong> under <strong>Event data</strong> in the side menu. It&#39;s there whether the event is in setup, live or finished.</p><p><img src="'+r+'" alt="The SportIdent station screen: a Station memory panel with the reader connected, Read backup and Clear memory buttons, a Station clock panel with Read time and Set to PC time, and an empty Backup records list"></p><ol><li><strong>Connect the reader</strong>, if it isn&#39;t already (<strong>Connected</strong> shows at the top of the panel).</li><li><strong>Place the remote station</strong> (the unit you&#39;re reading) against the direct station with the coupling rod.</li><li>Click <strong>Read backup</strong>. Manager shows the unit&#39;s mode (<strong>START</strong>, <strong>CHECK</strong>, <strong>FINISH</strong>, or the control it&#39;s set as), how many records it holds, and whether it uses SportIdent&#39;s extended or legacy protocol, then reads its memory. The records appear under <strong>Backup records</strong>, each with its card number, the competitor it matches, and the date and time of the punch.</li></ol><h3 id="reviewing-the-records" tabindex="-1">Reviewing the records <a class="header-anchor" href="#reviewing-the-records" aria-label="Permalink to &quot;Reviewing the records&quot;">​</a></h3><p>The list opens on <strong>Missing</strong>: records that would change something, leaving out the ones Manager has already applied. <strong>All</strong> shows every record. Every record in <strong>Missing</strong> starts ticked, so applying takes the whole memory; untick anything you want left out, such as a stale card from last weekend.</p><ul><li><strong>Today only</strong> is on to begin with, and hides records not dated today on this computer&#39;s clock. <strong>Reading a station the day after the event? Switch it off</strong>, or nothing shows.</li><li><strong>Time not recorded</strong> — the record has no usable time. It&#39;s still applied, with the time left blank: the card touched the unit, and that&#39;s what you&#39;re reading the memory for.</li><li><strong>Date unreadable</strong> — the record&#39;s date didn&#39;t decode, so it may be damaged. It starts unticked; tick it to apply it. Its time is never used.</li></ul><h3 id="applying-them" tabindex="-1">Applying them <a class="header-anchor" href="#applying-them" aria-label="Permalink to &quot;Applying them&quot;">​</a></h3><p>Click <strong>Apply to selected</strong>. Each record is recorded on the matching competitor as a station download, and their status changes:</p><table tabindex="0"><thead><tr><th>Unit</th><th>What applying does</th></tr></thead><tbody><tr><td><strong>Start</strong></td><td>Someone not yet started is marked <strong>On course</strong>.</td></tr><tr><td><strong>Check</strong></td><td>They&#39;re checked in, and counted on your On course list until they&#39;re back. Their status doesn&#39;t change.</td></tr><tr><td><strong>Finish</strong></td><td>Anyone with no status, or still on course, is marked <strong>DNF</strong>: they came back, but there&#39;s no result until their card is downloaded.</td></tr></tbody></table><p>A finished competitor, or one with a status you set, isn&#39;t changed, except that a <strong>DNS</strong> nothing had seen is taken back when a station shows them. The full rules, and why the order you read stations in doesn&#39;t matter, are in <a href="./safety-check#applying-station-records-also-changes-status">Applying station records also changes status</a>.</p><p>Afterwards Manager reports what happened: how many were applied, how many were <strong>already set</strong>, how many <strong>failed</strong> (each listed by card with the reason), and any DNS it took back, by name. Applying the same memory again is safe: records already applied are skipped.</p><h3 id="cards-nobody-is-entered-on" tabindex="-1">Cards nobody is entered on <a class="header-anchor" href="#cards-nobody-is-entered-on" aria-label="Permalink to &quot;Cards nobody is entered on&quot;">​</a></h3><p>Records whose card isn&#39;t held by anyone in the event are listed under <strong>Unmatched cards</strong>. From a start or check unit, <strong>Create unknown competitors</strong> adds an <strong>Unknown</strong> competitor for each, on course or checked in, so a runner nobody knew about is on the list to account for. Unmatched cards from a <strong>finish</strong> unit are listed for information only: someone who came back isn&#39;t missing.</p><h3 id="who-is-accounted-for" tabindex="-1">Who is accounted for <a class="header-anchor" href="#who-is-accounted-for" aria-label="Permalink to &quot;Who is accounted for&quot;">​</a></h3><p>Once a start, check or finish unit has been read in full, the panel shows <strong>Who is accounted for</strong>, and keeps it up to date:</p><ul><li><strong>No record of starting</strong> — entered competitors nothing has seen. After the check or start unit is read with everyone gone, these are your non-starters: <strong>Review</strong>, untick anyone you know started, and <strong>Mark as DNS</strong>.</li><li><strong>Still out</strong> — competitors something saw go out, and nothing has seen come back. After the finish unit is read, this is the list to chase.</li></ul><p>If some of the memory&#39;s records weren&#39;t applied, the panel says how many, because they may name someone it lists as unseen. See <a href="./safety-check#who-is-accounted-for">Who is accounted for</a>.</p><h3 id="recovered-punches-and-radio-punches" tabindex="-1">Recovered punches and radio punches <a class="header-anchor" href="#recovered-punches-and-radio-punches" aria-label="Permalink to &quot;Recovered punches and radio punches&quot;">​</a></h3><p>A station download is kept separately from the radio punches. A runner whose finish the radio already heard isn&#39;t counted twice, and the card download still decides their result.</p><h2 id="clearing-a-station-s-memory" tabindex="-1">Clearing a station&#39;s memory <a class="header-anchor" href="#clearing-a-station-s-memory" aria-label="Permalink to &quot;Clearing a station&#39;s memory&quot;">​</a></h2><p><strong>Clear memory</strong> erases every record in the unit, after you confirm. It can&#39;t be undone.</p><p>Clear a unit&#39;s memory <strong>before</strong> an event, so that last event&#39;s cards don&#39;t appear in it, and only after you&#39;ve read anything you might need. Don&#39;t clear a unit during an event: its memory is the backup for the radio.</p><h2 id="the-station-clock" tabindex="-1">The station clock <a class="header-anchor" href="#the-station-clock" aria-label="Permalink to &quot;The station clock&quot;">​</a></h2><p><strong>Read time</strong> shows the unit&#39;s clock and how far it is ahead of or behind this computer. <strong>Set to PC time</strong> sets it to this computer&#39;s time. Check every unit&#39;s clock before it goes out: a unit with the wrong time puts every punch in the wrong place. If one was out on the day, correct its punches with a <strong>Time Offset</strong> on the control rather than changing the unit&#39;s clock afterwards. See <a href="./../event-setup/controls-and-radio-controls#time-offset">Time Offset</a>.</p><h2 id="when-something-goes-wrong" tabindex="-1">When something goes wrong <a class="header-anchor" href="#when-something-goes-wrong" aria-label="Permalink to &quot;When something goes wrong&quot;">​</a></h2><ul><li><strong>&quot;The direct station was left in an unknown mode&quot;.</strong> Reading switches the direct station to remote mode and back. If that was interrupted, disconnect the reader and connect it again, from here or anywhere else. Card downloads may not work until you do.</li><li><strong>&quot;This station is in … mode, so its memory holds whole card images&quot;.</strong> A unit set up to store card images keeps nothing Manager can read back.</li><li><strong>&quot;The station&#39;s memory has filled and wrapped&quot;.</strong> The oldest records were overwritten by newer ones and are gone. Read units more often, or clear them before each event.</li><li><strong>A read stops part-way, or reports the wrong part of the memory.</strong> Check the coupling rod is seated, then read the memory again.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./safety-check">Safety check: accounting for everyone</a></li><li><a href="./who-is-still-on-course">Who is still on course</a></li><li><a href="./radio-punches">Radio punches</a></li><li><a href="./card-download">Downloading cards</a></li><li><a href="./../reference/station-configuration">Station configuration</a> — setting a unit&#39;s code, mode and switch-off time, and programming many units at once</li><li><a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a></li></ul>',37)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
